const FIELDS = [
    'Account.Name',
    'Account.Industry',
    'Account.AnnualRevenue',
    'Account.Owner.Name'
];

export default class AccountHeader extends LightningElement {
    @api recordId;

    @wire(getRecord, { recordId: '$recordId', fields: FIELDS })
    account;

    get hasData() {
        return this.account.data !== undefined;
    }

    get hasError() {
        return this.account.error !== undefined;
    }

    get errorMessage() {
