import { LightningElement, track } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

export default class ContactSearch extends LightningElement {
    @track results = [];
    @track error = null;

    _debounceTimer = null;
    _requestId = 0;

    get hasResults() {
        return this.results.length > 0;
    }

    handleSearch(event) {
        const value = event.target.value;

        // Clear any pending debounce
        if (this._debounceTimer) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = null;
        }

        const trimmed = value.trim();

        if (trimmed.length < 2) {
            // Invalidate any in-flight response so it will be ignored
            this._requestId++;
            this.results = [];
            this.error = null;
            return;
        }

        this._debounceTimer = setTimeout(() => {
            this._debounceTimer = null;
            this._executeSearch(trimmed);
        }, 300);
    }

    async _executeSearch(term) {
        const currentRequestId = ++this._requestId;
        this.error = null;

        try {
            const contacts = await searchContacts({ searchTerm: term });
            if (currentRequestId === this._requestId) {
                this.results = contacts || [];
            }
        } catch (error) {
            if (currentRequestId === this._requestId) {
                this.error = error.body ? error.body.message : error.message;
                this.results = [];
            }
        }
    }

    disconnectedCallback() {
        if (this._debounceTimer) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = null;
        }
        this._requestId++;
    }
}
