import { LightningElement, wire } from 'lwc';
import {
    MessageContext,
    subscribe,
    unsubscribe,
    publish,
    APPLICATION_SCOPE
} from 'lightning/messageService';
import Account_Selected from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    selectedRecordId = null;

    @wire(MessageContext)
    handleMessageContext({ value, error }) {
        if (value) {
            // Ensure we never hold more than one subscription
            if (this._messageContext) {
                unsubscribe(this._messageContext);
            }
            this._messageContext = value;
            this._subscription = subscribe(
                this._messageContext,
                Account_Selected,
                (message) => {
                    this.selectedRecordId = message.recordId || null;
                },
                { scope: APPLICATION_SCOPE }
            );
        }
    }

    disconnectedCallback() {
        if (this._messageContext) {
            unsubscribe(this._messageContext);
            this._messageContext = null;
        }
    }

    get hasSelectedAccount() {
        return this.selectedRecordId !== null;
    }

    handleClear() {
        if (this._messageContext) {
            publish(this._messageContext, Account_Selected, { recordId: null });
        }
    }
}
