import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import LightningConfirm from 'lightning/confirm';
import { deleteRecord } from 'lightning/uiRecordApi';
import { ShowToastEvent } from 'lightning/toast';

const COLUMNS = [
    { field: 'Name', label: 'Name' },
    { field: 'StageName', label: 'Stage' },
    { field: 'Amount', label: 'Amount', type: 'currency' },
    {
        type: 'action',
        typeAttributes: {
            rowActions: [
                { label: 'View', name: 'view' },
                { label: 'Edit', name: 'edit' },
                { label: 'Delete', name: 'delete' }
            ]
        }
    }
];

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    @api opportunities;

    get columns() {
        return COLUMNS;
    }

    get data() {
        return this.opportunities || [];
    }

    handleRowAction(event) {
        const { name } = event.detail.action;
        const row = event.detail.row;

        switch (name) {
            case 'view':
                this.navigateRecord(row.Id, 'view');
                break;
            case 'edit':
                this.navigateRecord(row.Id, 'edit');
                break;
            case 'delete':
                this.confirmDelete(row);
                break;
        }
    }

    navigateRecord(recordId, actionName) {
        const recordPage = NavigationMixin.generateRecordUrl({
            recordId: recordId,
            objectApiName: 'Opportunity',
            actionName: actionName
        });
        NavigationMixin.navigate({ url: recordPage });
    }

    confirmDelete(row) {
        LightningConfirm.open({
            label: 'Delete Opportunity',
            message: `Are you sure you want to delete "${row.Name}"?`,
            confirmLabel: 'Delete',
            cancelLabel: 'Cancel'
        }).then((confirmed) => {
            if (confirmed) {
                deleteRecord(row.Id)
                    .then(() => {
                        this.opportunities = this.opportunities.filter(
                            (opp) => opp.Id !== row.Id
                        );
                        this.dispatchEvent(
                            new ShowToastEvent({
                                title: 'Opportunity deleted',
                                message: `Opportunity "${row.Name}" was deleted.`,
                                variant: 'success'
                            })
                        );
                    })
                    .catch((error) => {
                        this.dispatchEvent(
                            new ShowToastEvent({
                                title: 'Delete failed',
                                message: error.body.message,
                                variant: 'error'
                            })
                        );
                    });
            }
        });
    }
}
