import { LightningElement, api } from 'lwc';
import LineItemEditor from 'c/lineItemEditor';

export default class OrderLinesPanel extends LightningElement {
    @api lines = [];
    showError = false;

    handleClick(event) {
        const action = event.target.getAttribute('data-action');
        if (action === 'reset') {
            this.handleReset();
        } else if (action === 'submit') {
            this.handleSubmit();
        }
    }

    handleReset() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        editors.forEach((editor) => editor.reset());
    }

    handleSubmit() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        let allValid = true;

        // Validate every editor so all invalid lines show their errors at once
        editors.forEach((editor) => {
            if (!editor.validate()) {
                allValid = false;
            }
        });

        if (allValid) {
            const values = editors.map((editor) => editor.getValue());
            this.showError = false;
            this.dispatchEvent(
                new CustomEvent('submit', {
                    detail: { lines: values },
                    bubbles: true,
                    composed: true
                })
            );
        } else {
            this.showError = true;
        }
    }
}
