import { LightningElement, api } from 'lwc';

let uid = 0;

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value = '';
    _activeIndex = 0;
    _instanceId = ++uid;

    @api get options() {
        return this._options;
    }
    set options(val) {
        this._options = val || [];
        this._updateActiveIndex();
    }

    @api get value() {
        return this._value;
    }
    set value(val) {
        this._value = val || '';
        this._updateActiveIndex();
    }

    get activeDescendantId() {
        if (this._options.length === 0) {
            return '';
        }
        return this._getOptionId(this._activeIndex);
    }

    get optionsWithMeta() {
        return this._options.map((opt, i) => ({
            id: this._getOptionId(i),
            value: opt.value,
            label: opt.label,
            isSelected: String(opt.value === this._value)
        }));
    }

    _getOptionId(index) {
        return `statusListbox-${this._instanceId}-option-${index}`;
    }

    _updateActiveIndex() {
        if (this._options.length === 0) {
            this._activeIndex = 0;
            return;
        }
        const idx = this._options.findIndex((o) => o.value === this._value);
        this._activeIndex = idx >= 0 ? idx : 0;
    }

    handleKeydown(event) {
        const { key } = event;

        if (this._options.length === 0) {
            return;
        }

        switch (key) {
            case 'ArrowDown':
                event.preventDefault();
                if (this._activeIndex < this._options.length - 1) {
                    this._activeIndex++;
                }
                break;
            case 'ArrowUp':
                event.preventDefault();
                if (this._activeIndex > 0) {
                    this._activeIndex--;
                }
                break;
            case 'Home':
                event.preventDefault();
                this._activeIndex = 0;
                break;
            case 'End':
                event.preventDefault();
                this._activeIndex = this._options.length - 1;
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this._selectOption(this._activeIndex);
                break;
            default:
                break;
        }
    }

    handleClick(event) {
        const clickedValue = event.currentTarget.dataset.value;
        const index = this._options.findIndex((o) => o.value === clickedValue);
        if (index >= 0) {
            this._activeIndex = index;
            this._selectOption(index);
        }
    }

    _selectOption(index) {
        const newValue = this._options[index].value;
        if (newValue === this._value) {
            return;
        }
        this._value = newValue;
        this.dispatchEvent(
            new CustomEvent('change', { detail: { value: newValue } })
        );
    }
}
