public class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    private static final String GIFT_TEMPLATE_NAME = 'Individual Gift';

    /**
     * Stages one NPSP Data Import record per gift, processes them synchronously
     * via the NPSP Data Importer Apex API, and returns one ImportResult per gift
     * in the original input order.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // 1. Resolve the NPSP Data Import template
        Id templateId = getGiftTemplateId();

        // 2. Stage one npe01__DataImport__c per gift
        List<npe01__DataImport__c> dataImports = new List<npe01__DataImport__c>();
        for (Integer i = 0; i < gifts.size(); i++) {
            dataImports.add(new npe01__DataImport__c(
                npe01__DataImportTemplate__c = templateId
            ));
        }
        insert dataImports;

        // 3. Stage field values (npe01__DataImportField__c) for each record
        List<npe01__DataImportField__c> allFields = new List<npe01__DataImportField__c>();
        for (Integer i = 0; i < gifts.size(); i++) {
            WebGift gift = gifts[i];
            Id diId = dataImports[i].Id;

            allFields.add(buildField(diId, 'FirstName', gift.firstName));
            allFields.add(buildField(diId, 'LastName',  gift.lastName));
            allFields.add(buildField(diId, 'Email',     gift.email));
            allFields.add(buildField(diId, 'Amount',    String.valueOf(gift.amount)));
            allFields.add(buildField(diId, 'Gift_Date', gift.giftDate.format('yyyy-MM-dd')));
        }
        insert allFields;

        // 4. Process synchronously in the current transaction
        List<Id> diIds = new List<Id>();
        for (npe01__DataImport__c di : dataImports) {
            diIds.add(di.Id);
        }
        npe01__ProcessDataImport.process(diIds);

        // 5. Read back the processed Data Import records
        Map<Id, npe01__DataImport__c> diMap = new Map<Id, npe01__DataImport__c>(
            [SELECT Id, npe01__Status__c, npe01__Error__c, npe01__Result__c
             FROM npe01__DataImport__c
             WHERE Id IN :diIds]
        );

        // 6. Build results in input order
        List<ImportResult> results = new List<ImportResult>();
        for (Integer i = 0; i < dataImports.size(); i++) {
            ImportResult result = new ImportResult();
            npe01__DataImport__c di = diMap.get(dataImports[i].Id);

            if (di != null && String.equals(di.npe01__Status__c, 'Imported')) {
                result.success = true;
                extractCreatedIds(di.npe01__Result__c, result);
            } else {
                result.success = false;
                result.errorMessage = (di != null && !String.isBlank(di.npe01__Error__c))
                    ? di.npe01__Error__c
                    : 'Data import failed with unknown error.';
            }

            results.add(result);
        }

        return results;
    }

    // ─── private helpers ───────────────────────────────────────────────────

    private static Id getGiftTemplateId() {
        List<npe01__DataImportTemplate__c> templates = [
            SELECT Id
            FROM npe01__DataImportTemplate__c
            WHERE npe01__Name__c = :GIFT_TEMPLATE_NAME
            LIMIT 1
        ];
        if (templates.isEmpty()) {
            throw new NoAccessException(
                'NPSP Data Import template "' + GIFT_TEMPLATE_NAME + '" was not found. ' +
                'Verify that NPSP Data Importer is installed and the gift template exists.'
            );
        }
        return templates[0].Id;
    }

    private static npe01__DataImportField__c buildField(Id dataImportId, String fieldName, String value) {
        return new npe01__DataImportField__c(
            npe01__DataImport__c = dataImportId,
            npe01__FieldName__c  = fieldName,
            npe01__FieldValue__c = value
        );
    }

    /**
     * Parses the NPSP result (JSON) to extract the IDs of the created
     * Contact and Opportunity. The expected JSON shape is:
     *   {"ContactId":"003...","OpportunityId":"006..."}
     */
    private static void extractCreatedIds(String result, ImportResult importResult) {
        if (String.isBlank(result)) {
            return;
        }
        try {
            Map<String, Object> map = (Map<String, Object>) JSON.deserializeUntyped(result);
            if (map.containsKey('ContactId')) {
                importResult.contactId = (Id) map.get('ContactId');
            }
            if (map.containsKey('OpportunityId')) {
                importResult.opportunityId = (Id) map.get('OpportunityId');
            }
        } catch (Exception e) {
            // Fallback: the result may be a plain ID string
            try {
                importResult.contactId = (Id) result;
            } catch (Exception e2) {
                // Cannot determine created IDs from result; leave null
            }
        }
    }
}
