public class HouseholdService {

    /**
     * Creates a single NPSP Household Account and assigns all provided contacts to it.
     * The first contact in the list becomes the household's primary contact.
     * The account name is left to NPSP's automatic naming logic.
     *
     * @param members  New (unsaved) Contact records to place in the household.
     * @return         The Id of the newly created Household Account.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty');
        }

        // Look up the Household Record Type by developer name (no hard-coded Ids)
        RecordType householdRT = [
            SELECT Id
            FROM RecordType
            WHERE SobjectType = 'Account'
              AND DeveloperName = 'Household'
            LIMIT 1
        ];

        // Create the household without a name – NPSP will auto-name it
        Account household = new Account(
            RecordTypeId = householdRT.Id
        );
        insert household;

        // Assign every contact to the new household
        for (Contact c : members) {
            c.AccountId = household.Id;
        }
        insert members;

        // Make the first contact the primary contact
        household.Primary_Contact__c = members[0].Id;
        update household;

        return household.Id;
    }
}
