public class OPP_MajorGiftFollowUp_TDTM extends NPE01_TriggerHandler {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;

    public override Boolean handleInsert(List<SObject> newRecords) {
        List<Task> tasks = new List<Task>();
        for (SObject sObj : newRecords) {
            Opportunity opp = (Opportunity) sObj;
            if (isMajorGift(opp)) {
                tasks.add(buildTask(opp));
            }
        }
        if (!tasks.isEmpty()) {
            Insert tasks;
        }
        return true;
    }

    public override Boolean handleUpdate(List<SObject> newRecords, Map<Id, SObject> oldRecords) {
        List<Task> tasks = new List<Task>();
        for (SObject sObj : newRecords) {
            Opportunity opp = (Opportunity) sObj;
            if (!isMajorGift(opp)) {
                continue;
            }
            Opportunity oldOpp = (Opportunity) oldRecords.get(opp.Id);
            if (oldOpp != null && isMajorGift(oldOpp)) {
                continue;
            }
            tasks.add(buildTask(opp));
        }
        if (!tasks.isEmpty()) {
            Insert tasks;
        }
        return true;
    }

    private static Boolean isMajorGift(Opportunity opp) {
        return opp.StageName == STAGE_CLOSED_WON
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_THRESHOLD;
    }

    private static Task buildTask(Opportunity opp) {
        Task t = new Task(
            Subject = 'Major gift thank-you call',
            Priority = 'High',
            Status = 'Not Started',
            WhatId = opp.Id,
            WhoId = opp.npsp__Primary_Contact__c,
            OwnerId = opp.OwnerId,
            ActivityDate = (opp.CloseDate != null) ? opp.CloseDate.addDays(3) : null
        );
        return t;
    }
}
```

**Key design decisions:**

| Concern | How it's handled |
|---|---|
| **TDTM integration** | Extends `NPE01_TriggerHandler`; the NPSP dispatcher calls `handleInsert` / `handleUpdate` based on the registered Trigger Handler record. Deactivating that record stops the handler—no trigger file needed. |
| **No SOQL** | The "before" state on update comes from the `oldRecords` map that NPSP's trigger framework passes in, so zero queries. |
| **Single DML** | All qualifying Tasks are collected into one list and inserted with a single `Insert tasks;` statement. |
| **Idempotency on update** | An opportunity that was *already* Closed Won ≥ 5 000 in the old snapshot is skipped, so re-saving or editing a qualified gift never creates a duplicate Task. |
| **Null safety** | `Amount` is checked for null; `npsp__Primary_Contact__c` is allowed to be null (WhoId simply stays null); `CloseDate` is guarded before adding days. |

