public class TA_Contact_PreventDuplicateEmail implements Trigger_Action__ifc {

    public void execute() {
        if (!Trigger.isInsert && !Trigger.isUpdate) {
            return;
        }

        List<Contact> checkedRecords = new List<Contact>();

        if (Trigger.isInsert) {
            for (Contact c : Trigger.new) {
                if (String.isNotBlank(c.AccountId) && String.isNotBlank(c.Email)) {
                    checkedRecords.add(c);
                }
            }
        } else {
            for (Integer i = 0; i < Trigger.new.size(); i++) {
                Contact newC = Trigger.new[i];
                Contact oldC = Trigger.old[i];
                Boolean emailChanged = newC.Email != oldC.Email;
                Boolean accountIdChanged = newC.AccountId != oldC.AccountId;
                if ((emailChanged || accountIdChanged)
                    && String.isNotBlank(newC.AccountId)
                    && String.isNotBlank(newC.Email)) {
                    checkedRecords.add(newC);
                }
            }
        }

        if (checkedRecords.isEmpty()) {
            return;
        }

        // Collect distinct AccountIds for the SOQL query
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : checkedRecords) {
            accountIds.add(c.AccountId);
        }

        // Single SOQL: fetch all contacts on the relevant accounts
        Map<String, Set<Id>> existingByKey = new Map<String, Set<Id>>();
        for (Contact c : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
        ]) {
            if (String.isBlank(c.Email) || String.isBlank(c.AccountId)) {
                continue;
            }
            String key = c.AccountId + '|' + String.toLowerCase(c.Email);
            if (!existingByKey.containsKey(key)) {
                existingByKey.put(key, new Set<Id>());
            }
            existingByKey.get(key).add(c.Id);
        }

        // On update, remove the records being updated from the existing map
        // (their DB values are stale; they will have the new values after save)
        if (Trigger.isUpdate) {
            Set<Id> checkedIds = new Set<Id>();
            for (Contact c : checkedRecords) {
                checkedIds.add(c.Id);
            }
            for (String key : existingByKey.keySet()) {
                existingByKey.get(key).removeAll(checkedIds);
                if (existingByKey.get(key).isEmpty()) {
                    existingByKey.remove(key);
                }
            }
        }

        // Process in list order: first record claiming a key is accepted,
        // subsequent records with the same key are rejected.
        Set<String> claimedKeys = new Set<String>();

        for (Contact c : checkedRecords) {
            String key = c.AccountId + '|' + String.toLowerCase(c.Email);

            Boolean hasConflict = false;

            // Another record in this batch already claimed the same account+email
            if (claimedKeys.contains(key)) {
                hasConflict = true;
            }

            // An existing contact in the database already uses this account+email
            if (!hasConflict && existingByKey.containsKey(key)) {
                hasConflict = true;
            }

            if (hasConflict) {
                c.addError('Another contact on this account already uses this email address.');
            } else {
                claimedKeys.add(key);
            }
        }
    }
}
